// ==============================================================================
// Week 2: 사내 매뉴얼 마크다운 로드 및 구조화 메타데이터 주입
// ==============================================================================
const item = $input.first();
let textContent = "";

// 바이너리 데이터(파일 읽기) 또는 텍스트 입력 처리
if (item.binary && item.binary.data) {
  const binaryBuffer = Buffer.from(item.binary.data.data, 'base64');
  textContent = binaryBuffer.toString('utf-8');
} else if (item.json && item.json.content) {
  textContent = item.json.content;
} else if (typeof item.json === 'string') {
  textContent = item.json;
} else {
  textContent = JSON.stringify(item.json);
}

// 문서 메타데이터 기본값 추출 및 정제
const docIdMatch = textContent.match(/문서 번호[\*\s]*:[\s]*`?([A-Za-z0-9_-]+)`?/);
const docVersionMatch = textContent.match(/문서 버전[\*\s]*:[\s]*`?([vV0-9.]+)?`?/);
const secLevelMatch = textContent.match(/보안 등급[\*\s]*:[\s]*([가-힣A-Za-z\s\(\)]+)/);

const docId = docIdMatch ? docIdMatch[1] : "DOC-ITSM-2026-SOP";
const docVersion = docVersionMatch ? docVersionMatch[1] : "v3.4";
const securityLevel = secLevelMatch ? secLevelMatch[1].trim() : "Internal Enterprise Confidential";

// 대단원(## ) 단위로 1차 분할하여 섹션 메타데이터 부여
const rawSections = textContent.split(/(?=^##\s+)/m);
const documents = [];

for (let i = 0; i < rawSections.length; i++) {
  const sectionBlock = rawSections[i].trim();
  if (!sectionBlock) continue;

  // 섹션 제목 추출 (첫 번째 행)
  const firstLine = sectionBlock.split('\n')[0].replace(/^##\s*/, '').trim();
  const sectionName = firstLine.length > 0 ? firstLine : `Section-${i}`;

  documents.push({
    json: {
      text: sectionBlock,
      metadata: {
        doc_id: docId,
        doc_version: docVersion,
        security_level: securityLevel,
        section_index: i,
        section: sectionName,
        indexed_at: new Date().toISOString(),
        source: "/data/sample_docs/sla_and_troubleshooting_manual.md"
      }
    }
  });
}

return documents;

// ==============================================================================
// Week 2: RAG 질의 텍스트 추출 및 정규화
// ==============================================================================
const input = $input.first().json;

const query = input.body?.query || input.query || input.body?.question || input.question || "";
const companyName = input.body?.company_name || input.company_name || "미상 고객사";
const contractTier = input.body?.contract_tier || input.contract_tier || "Unknown";

if (!query || String(query).trim().length === 0) {
  throw new Error("유효한 query 필드가 페이로드에 누락되었습니다.");
}

return [{
  json: {
    query: String(query).trim(),
    company_name: companyName,
    contract_tier: contractTier,
    received_at: new Date().toISOString()
  }
}];

// ==============================================================================
// Week 2: 검색된 Top-K 청크 취합 및 Grounding 프롬프트 컨텍스트 생성
// ==============================================================================
const retrievedItems = $input.all();
const originalQueryData = $("Preprocess and Validate Query").first().json;

let contextBlocks = [];
let referencedSections = [];

for (let i = 0; i < retrievedItems.length; i++) {
  const item = retrievedItems[i].json;
  const pageContent = item.pageContent || item.text || item.document || "";
  const meta = item.metadata || {};

  const sectionName = meta.section || `참조 섹션 ${i + 1}`;
  const docId = meta.doc_id || "DOC-ITSM-2026-SOP";
  const secLevel = meta.security_level || "Internal Enterprise Confidential";

  if (sectionName && !referencedSections.includes(sectionName)) {
    referencedSections.push(sectionName);
  }

  contextBlocks.push(
`[문서 발췌 ${i + 1}]
- 문서 ID: ${docId}
- 섹션: ${sectionName}
- 보안 등급: ${secLevel}
[내용]:
${pageContent.trim()}`
  );
}

const combinedContext = contextBlocks.join("\n\n----------------------------------------\n\n");

return [{
  json: {
    query: originalQueryData.query,
    company_name: originalQueryData.company_name,
    contract_tier: originalQueryData.contract_tier,
    retrieved_count: retrievedItems.length,
    context: combinedContext,
    referenced_sections: referencedSections
  }
}];

// ==============================================================================
// Week 2: 최종 반환 응답 JSON 구조화 및 출처 메타데이터 바인딩
// ==============================================================================
const llmOutput = $input.first().json.text || $input.first().json.response || "";
const contextData = $("Assemble Grounded Context").first().json;

// 환각 방어 거절 응답 여부 판별
const isGroundingRefusal = llmOutput.includes("사내 표준 매뉴얼에서 해당") || llmOutput.includes("확인할 수 없습니다");

return [{
  json: {
    status: "success",
    query: contextData.query,
    company_name: contextData.company_name,
    contract_tier: contextData.contract_tier,
    answer: llmOutput.trim(),
    grounding_verified: !isGroundingRefusal,
    referenced_sections: contextData.referenced_sections,
    chunks_retrieved_count: contextData.retrieved_count,
    processed_at: new Date().toISOString()
  }
}];
